LEFT JOIN BookingAcknowledgement BA ON BR.BookingID = BA.BookingID AND MR.MaintenanceID = BA.MaintenanceID
WHERE MR.ImpactLevel = 'Advisory'
  AND BR.StartTime < ISNULL(MR.CompletionTime, '2099-12-31')
