JOIN [User] U ON BR.RequesterID = U.UserID
JOIN [Space] S ON BR.SpaceCode = S.SpaceCode
WHERE BR.StartTime >= '2024-09-30 12:00:00' AND BR.EndTime <= '2024-09-30 14:00:00'
GROUP BY U.Department, S.SpaceType
